import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>亮度、曝光和对比度是每个修图软件都有的三个控制，很容易搞混。三个都能让照片变亮或者变暗，但做法完全不一样。</p>\n<p>用错了，结果反而更糟。需要对比度的照片只提亮，会看着发灰；需要亮度的照片只加对比度，会看着很生硬。</p>\n<p>这篇文章会把每个控制讲清楚：它们有什么不同、怎么互相影响、不同情况下该用哪一个。这是所有修图操作的基础。想亲手感受三个控制的区别，<a href=\"/zh/tiaozheng-tupian-liangdu/\">图片亮度调节</a>里拖动滑块就能实时看到亮度变化。</p>\n<h2 id=\"what-each-does\">每个控制是干什么的</h2>\n<p>亮度是把每个像素一起往白或者往黑推，整张图均匀变化。最简单，适合修整张偏暗或者偏亮的照片。</p>\n<p>曝光是改变图片看起来“拍到了多少光”。它对高光和阴影的影响不一样，两端保留的细节比亮度更多。</p>\n<p>对比度是拉大或者压缩图片最暗和最亮部分的距离。调高，暗部更暗、亮部更亮；调低，整张图都往中间靠。</p>\n<p>可以这样记：亮度是整体移动，对比度是拉伸，曝光是重塑。每个解决的问题都不一样。</p>\n<h2 id=\"brightness-explained\">亮度，简单讲</h2>\n<p>亮度是均匀移动。每个像素变亮或者变暗的幅度都一样，东西之间的相对差别保持不变。</p>\n<p>整张偏暗或者偏亮的照片，用亮度修最快。室内暗照提亮 15%，立刻就能看清楚，效果也很好预测。</p>\n<p>亮度的短板在两端。推得太远，高光会被洗成没有细节的死白，因为所有像素是一起移动的。</p>\n<p>整张照片都要往上或者往下调时，用亮度。只有一部分暗的照片，亮度修不好，因为它会把亮的部分也一起动了。</p>\n<h2 id=\"exposure-explained\">曝光，简单讲</h2>\n<p>曝光模拟的是相机的同名设置。相机里曝光是感光元件接收了多少光，编辑器里曝光就是模拟改变这个量。</p>\n<p>和亮度不一样，曝光对色调范围的影响不均匀。它对中间调影响最大，对极端高光和阴影影响较小，所以保留的细节更多。</p>\n<p>高光很重要的时候，曝光是更好的选择。亮度调整可能洗白的天空，在曝光调整下还能保住形状。</p>\n<p>很多浏览器编辑器只提供亮度，因为实现起来更简单。只有亮度可用时，小步调整、每次检查高光，效果也接近。</p>\n<h2 id=\"contrast-explained\">对比度，简单讲</h2>\n<p>对比度讲的是差别。高对比度的图片，黑色很深、白色很亮，两端差距很大；低对比度的图片，所有色调都挤在中间。</p>\n<p>调高对比度，暗部更暗、亮部更亮。发灰的照片立刻有了冲击力和深度，但也可能把阴影压成死黑、高光裁成死白。</p>\n<p>调低对比度正好相反。图片变柔和，明暗两端往中间靠，适合有雾的照片和柔和的人像。</p>\n<p>照片整体亮度没问题、看着却发灰时，用对比度。问题不在亮度高低，而在色调拉得不够开。</p>\n<h2 id=\"how-they-interact\">三个控制怎么互相影响</h2>\n<p>亮度和对比度直接互相影响。提亮常常让照片发平，因为阴影被抬起来，明暗差距变小了；加对比度能把这个差距找回来。</p>\n<p>曝光和对比度也互相影响。曝光提亮可能洗掉高光，加对比度能把曝光拿走的深度找回来。</p>\n<p>常见的做法是先调亮度，再调对比度。亮度定好整体水平，对比度再围绕这个水平精修色调分布。</p>\n<p>动一个控制，另一个的需求也会变。大幅提亮之后，重新检查对比度；大幅加对比之后，重新检查亮度。</p>\n<h2 id=\"when-to-use-brightness\">什么时候用亮度</h2>\n<p>整张照片太暗或者太亮时，用亮度。室内暗照、阴天发灰的风景、脏兮兮的扫描件，都需要整体提亮。</p>\n<p>截图和文档也适合用亮度。文字必须看得清，均匀提亮能让偏暗的扫描件立刻变清楚，又不改变它的样子。</p>\n<p>照片要放在文字下面时，用亮度调暗。调暗的图片能让白色文字看得清，适合幻灯片和海报。</p>\n<p>只有一部分有问题时，别用亮度。前景暗、天空亮的照片，亮度会把两部分一起动，顾此失彼。</p>\n<h2 id=\"when-to-use-exposure\">什么时候用曝光</h2>\n<p>高光很重要时，用曝光。细节丰富的天空、高光明显的皮肤、有反光面的商品，都需要曝光更温和的手法。</p>\n<p>照片只是稍微差一点时，曝光也是更好的选择。小幅曝光调整能修正亮度，又不会像大幅提亮那样洗白画面。</p>\n<p>编辑器只有亮度时，可以模拟曝光：小步提亮，每步检查高光。大多数照片用这个办法，效果也足够接近。</p>\n<p>强阳光下拍的照片，用曝光更保险。它能在提亮阴影的同时保住亮部，亮度做不到这一点。</p>\n<h2 id=\"when-to-use-contrast\">什么时候用对比度</h2>\n<p>照片整体亮度没问题、看着却发灰时，用对比度。问题在色调分布，不在亮度高低，只有对比度能修分布。</p>\n<p>有雾的照片、雾蒙蒙的风景、发灰的室内照，都适合对比度。轻轻一推，图片就有了冲击力，感觉扎实了。</p>\n<p>想柔化一张生硬的照片，用负对比度。正午人像的阴影太重，调低对比能让生硬的边缘变柔和。</p>\n<p>阴影或者高光里有重要细节的照片，别大幅加对比。两端最先被裁掉，裁掉的天空和压死的阴影都找不回来。</p>\n<h2 id=\"order-of-edits\">正确顺序：先亮度，再对比度</h2>\n<p>先调亮度，因为它定整体水平。太暗的照片要先提亮，才能判断对比度；太亮的照片要先调暗。</p>\n<p>再调对比度。亮度定好之后，就能看出图片是发平还是有冲击力，小幅调整对比就能修正分布。</p>\n<p>最后再检查一遍亮度。对比度变化会让图片感觉变暗或者变亮，之后再微调一下亮度，效果常常更好。</p>\n<p>每一步都小幅度来。亮度 10% 加对比度 10%，比任何一个单独推 30% 都好控制。</p>\n<h2 id=\"portraits\">人像：哪个控制最重要</h2>\n<p>人像要轻提亮、谨慎加对比。脸太暗藏住了表情，对比度太高又会让脸看着生硬、显老。</p>\n<p>先轻轻提亮 10% 到 15%。看一眼肤色：应该看着是自然受光，而不是像近距离打了闪光灯。</p>\n<p>人像看着发平，再补对比度。10% 的小幅提升通常就够了，再大皮肤会看着粗糙。</p>\n<p>逆光人像没有哪个控制能同时修好人脸和背景。轻轻提亮，接受折中，或者重新拍一张。</p>\n<h2 id=\"landscapes\">风景：天空和前景怎么平衡</h2>\n<p>风景照常常是前景要提亮、天空要克制。整体提亮会把云朵洗白，前景是修好了，天空却没了。</p>\n<p>中等幅度提亮，先看天空。云朵失去形状，就是推过头了，幅度小一点才是正确答案。</p>\n<p>再加对比度，把提亮拿走的深度找回来。天空清晰、前景有细节的风景，需要两个控制一起工作。</p>\n<p>清晨和傍晚的风景最适合这对组合。低角度的光线色彩浓郁，轻轻提亮再加一点对比，细节就出来了。</p>\n<h2 id=\"screenshots\">截图和文档：亮度优先</h2>\n<p>截图和扫描文档更需要亮度，而不是对比度。目标是白底上文字清晰，均匀提亮直接就能做到。</p>\n<p>一直加亮度，直到文字清晰、背景变白。白底黑字的文档，又好读又好打印。</p>\n<p>提亮后文字还是发灰，再补一点对比。小幅提升能让字母变黑、边缘变锐，小字最受益。</p>\n<p>截图导出成 PNG。无损格式能让文字保持清晰，截图是用来看的，文件大小没那么重要。</p>\n<h2 id=\"text-over-photos\">照片上的文字：对比度是关键</h2>\n<p>照片上的文字，靠的是字母和背景之间的对比。亮底白字看不见，暗底黑字同样看不见。</p>\n<p>把文字后面的照片调暗，白色字母就看得清了。整张图降低 20% 到 30% 亮度，就能给文字造出一块暗区。</p>\n<p>或者提高照片的对比度，把明暗区域分得更开。高对比度的背景能让文字坐得更稳。</p>\n<p>想看完整的文字可读性指南，请读<a href=\"/zh/blog/tupian-shang-wenzi-qingxidu-duibidu/\">图片上的文字怎么才清晰？对比度与可读性指南</a>。</p>\n<h2 id=\"common-confusions\">三个控制最容易搞混的地方</h2>\n<p>最常见的混淆，是把亮度和对比度当成一回事。两者不一样：亮度移动整体水平，对比度改变分布，一张照片可能只需要其中一个。</p>\n<p>另一个混淆，是用亮度修发灰的照片。发灰的照片亮度本来就对，提亮只会让它更亮、更平，不会变好。</p>\n<p>还有人用对比度修偏暗的照片。偏暗的照片加了对比还是暗，只是阴影更深了，主体依然藏着。</p>\n<p>办法是先诊断再动手。问自己：照片是太暗、太灰，还是两者都有？诊断对了，控制就选对了。</p>\n<h2 id=\"testing-combinations\">动手之前先小步测试组合</h2>\n<p>亮度和对比度一起小步测试。偏暗又发灰的照片，亮度 10% 加对比度 10% 是很好的起点。</p>\n<p>每改一步都看一眼对比视图。分屏能准确显示每一步到底做了什么，觉得顺眼了就停下来。</p>\n<p>高光和阴影分开检查。亮度最先裁掉高光，对比度最先压死阴影，两端都要留意。</p>\n<p>组合效果比原图还糟，就重置重来。换更小的幅度重新试一次，通常比抢救一张改过头的图更有效。</p>\n<h2 id=\"cheat-sheet\">快速决策速查表</h2>\n<p>整张照片太暗或者太亮，用亮度。这是最快的整体修正办法，截图和文档最适合。</p>\n<p>高光很重要、编辑器又有曝光选项，用曝光。它比亮度更能保住亮部的细节，适合风景和人像。</p>\n<p>照片亮度没问题、看着却发灰，用对比度。小幅提升加冲击力，小幅降低柔化生硬的图片。</p>\n<p>照片两个问题都有，先亮度、再对比度。顺序很重要，亮度定水平，对比度再围绕这个水平精修分布。</p>\n<h2 id=\"three-controls-for-thumbnails\">视频封面图：三个控制怎么用</h2>\n<p>视频封面显示得很小，所以亮度和对比度都要够强。偏暗又发灰的封面在信息流里直接消失，明亮又有冲击力的封面才能抓住眼球。</p>\n<p>封面图可以比整图再亮一点。小尺寸藏不住细腻，明亮清晰的图片比有氛围的图片更管用。</p>\n<p>加对比度，把主体和背景分开。主体清晰、背景分明的封面，哪怕缩得很小也能一眼看懂。</p>\n<p>发布之前按真实尺寸测试一下。在手机上缩小看一眼，主体还清不清楚、有文字的话还看不看得清。</p>\n<p>想看实操步骤，请读<a href=\"/zh/blog/zenme-tiaozheng-tupian-liangdu/\">怎么调图片亮度：5步修好偏暗照片</a>和<a href=\"/zh/blog/zenme-tiaozheng-tupian-duibidu/\">怎么调图片对比度：5步拯救发灰照片</a>。想看完整指南，请读<a href=\"/zh/blog/tupian-liangdu-tiaozheng-zhinan/\">图片亮度调整完全指南：提亮暗照片不发灰</a>和<a href=\"/zh/blog/tupian-duibidu-tiaozheng-zhinan/\">图片对比度调整完全指南：让照片更有层次</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"亮度和对比度有什么区别？","answer":"亮度是把每个像素一起往白或者往黑推，整体上下移动色调范围。对比度是拉大或者压缩最暗和最亮部分的距离。偏暗的照片需要亮度，发灰的照片需要对比度，又暗又灰的照片两个都需要。"},{"question":"曝光和亮度是一回事吗？","answer":"不是，虽然用起来感觉差不多。曝光对高光和阴影的影响不一样，两端保留的细节更多；亮度是均匀移动所有像素。曝光对明亮的天空更温和，亮度更简单、更快，适合整体修正。"},{"question":"亮度和对比度先调哪一个？","answer":"先亮度，再对比度。亮度定好整体水平，对比度再围绕这个水平精修分布。调完对比度之后再检查一遍亮度，因为图片可能感觉变暗或者变亮了。"},{"question":"为什么提亮后照片看着发平？","answer":"提亮把阴影抬起来，明暗差距变小了，图片就发平了。之后补一点对比度，就能找回深度。亮度 10% 加对比度 10%，是偏暗又发灰照片很好的起点组合。"},{"question":"对比度能修好太暗的照片吗？","answer":"不能。对比度改变的是分布，不是整体水平，偏暗的照片加了对比还是暗，只是阴影更深了。先提亮修好整体水平，照片看着发平再加对比度。"},{"question":"有雾的风景照该用哪个控制？","answer":"对比度为主，亮度小幅辅助。雾把色调范围压平了，对比度能找回深度。如果照片还偏暗，先提亮 10%，再加 10% 到 20% 的对比度，检查一下天空。"}];
